import{_ as o,r as t,o as i,c as r,e as n,a as l,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Introduction to Tailor - October CMS User Guide","titleTemplate":false,"description":"How Tailor uses YAML blueprints to build your content management system","frontmatter":{"subtitle":"How Tailor uses YAML blueprints to build your content management system"},"headers":[{"level":2,"title":"Blueprints and Entries","slug":"blueprints-and-entries","link":"#blueprints-and-entries","children":[]},{"level":2,"title":"Where Blueprints Live","slug":"where-blueprints-live","link":"#where-blueprints-live","children":[]},{"level":2,"title":"Anatomy of a Blueprint","slug":"anatomy-of-a-blueprint","link":"#anatomy-of-a-blueprint","children":[]},{"level":2,"title":"Blueprint Types","slug":"blueprint-types","link":"#blueprint-types","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/content-management/tailor-introduction.md","filePath":"user-guide/quickstart/content-management/tailor-introduction.md"}'),c={name:"user-guide/quickstart/content-management/tailor-introduction.md"};function p(u,e,h,m,g,b){const a=t("pre-heading"),s=t("post-heading");return i(),r("div",null,[n(a),e[0]||(e[0]=l("h1",null,"Introduction to Tailor",-1)),n(s),e[1]||(e[1]=d(`<p>Tailor is October CMS&#39;s built-in content management system. It lets you define custom content types (team members, products, events, anything) using simple YAML files called <strong>blueprints</strong>. Once you create a blueprint, Tailor automatically generates the backend forms, list views, and database tables for you. No PHP code, no manual database setup.</p><h2 id="blueprints-and-entries"><a href="#blueprints-and-entries" class="header-anchor">#</a> Blueprints and Entries</h2><p>The two core concepts are:</p><ul><li><strong>Blueprints</strong> define the <em>structure</em>: what fields each piece of content has, how it appears in the backend, and what type of content it is.</li><li><strong>Entries</strong> are the actual content records you create. Each entry follows the structure defined by its blueprint.</li></ul><p>Think of a blueprint as a mold and entries as the things you make with it. A &quot;Team Member&quot; blueprint defines what a team member looks like (name, photo, email), and each person you add is an entry.</p><h2 id="where-blueprints-live"><a href="#where-blueprints-live" class="header-anchor">#</a> Where Blueprints Live</h2><p>Blueprints can live in two places:</p><ul><li><strong>In the app</strong> (<code>app/blueprints/</code>): These are globally available regardless of which theme is active. Use this for content that should persist across theme changes.</li><li><strong>In the theme</strong> (<code>themes/mytheme/blueprints/</code>): These only appear when that theme is selected. Use this for content that is specific to a theme&#39;s design.</li></ul><p>For this tutorial, we will create blueprints in the theme so they stay bundled with everything else we have built.</p><h2 id="anatomy-of-a-blueprint"><a href="#anatomy-of-a-blueprint" class="header-anchor">#</a> Anatomy of a Blueprint</h2><p>Every blueprint file has a few key properties:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Team\\Member
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Team Member
</code></pre></div><ul><li><strong><code>handle</code></strong>: A human-readable name that follows PHP namespace syntax (e.g., <code>Team\\Member</code>, <code>Site\\Settings</code>). You use this handle to reference the blueprint in your templates.</li><li><strong><code>type</code></strong>: The kind of content: <code>entry</code>, <code>global</code>, <code>single</code>, <code>structure</code>, <code>stream</code>, or <code>mixin</code>.</li><li><strong><code>name</code></strong>: The display name shown in the backend.</li></ul><p>Each blueprint also gets a <strong>UUID</strong> automatically, a unique identifier that determines the database table name. You do not need to set this yourself.</p><p>Because blueprints are identified by handle, they are totally portable. You can move them into any folder or subdirectory and they will continue to work.</p><h2 id="blueprint-types"><a href="#blueprint-types" class="header-anchor">#</a> Blueprint Types</h2><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><code>entry</code></td><td>A collection of items</td><td>Blog posts, team members, products</td></tr><tr><td><code>global</code></td><td>A single record for site-wide settings</td><td>Footer text, social links, display options</td></tr><tr><td><code>single</code></td><td>A one-off page with custom fields</td><td>About page, contact page</td></tr><tr><td><code>structure</code></td><td>Entries with parent-child nesting</td><td>Documentation sections, FAQ categories</td></tr><tr><td><code>stream</code></td><td>Time-ordered entries</td><td>News feed, changelog, activity log</td></tr><tr><td><code>mixin</code></td><td>Reusable field definitions</td><td>SEO fields shared across blueprints</td></tr></tbody></table></div><p>We will use <strong>entry</strong> and <strong>global</strong> in this tutorial.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Now that you understand what Tailor is, let&#39;s build something. Continue to <a href="./creating-blueprints.html">Creating Blueprints</a> to define a Team Members content type and a settings global.</p><p>For the full technical reference, see <a href="./../../../4.x/cms/tailor/introduction.html">Tailor Introduction</a> in the developer documentation.</p>`,21))])}const w=o(c,[["render",p]]);export{f as __pageData,w as default};
